INSERT INTO lessons (lesson_id, module_id, title, target_situation, order_index) VALUES
(105, 1, 'Chào khách và tìm hiểu nhu cầu mua hàng', 'Nhân viên bán hàng đón khách, hỏi nhu cầu và ngân sách.', 10),
(106, 1, 'Giới thiệu sản phẩm và hướng dẫn dùng thử', 'Giải thích chất liệu, tính năng và mời khách dùng thử.', 11),
(107, 1, 'Báo giá, giảm giá và xử lý so sánh giá', 'Giải thích giá niêm yết và ưu đãi cho khách.', 12),
(108, 1, 'Chốt đơn và xác nhận thanh toán', 'Xác nhận lựa chọn, số lượng, phương thức thanh toán.', 13),
(109, 1, 'Đổi trả và chăm sóc khách sau mua', 'Tiếp nhận yêu cầu đổi sản phẩm, kiểm tra biên lai và chính sách.', 14),
(205, 2, 'Hỏi người bản địa đường đến tháp Eiffel', 'Hỏi đường, trạm tàu và lối đi bộ khi tham quan Paris.', 15),
(206, 2, 'Mua vé và hỏi quy định tại bảo tàng Louvre', 'Hỏi vé, đặt trước và quy định chụp ảnh tại bảo tàng.', 16),
(207, 2, 'Hỏi hướng dẫn viên tại đấu trường Colosseum', 'Tìm tour tiếng Anh và hỏi về lịch sử công trình ở Rome.', 17),
(208, 2, 'Ứng xử lịch sự khi tham quan đền ở Kyoto', 'Hỏi quy tắc, xin phép chụp ảnh và tôn trọng không gian tín ngưỡng.', 18),
(209, 2, 'Nhờ người bản địa gợi ý và chụp ảnh', 'Hỏi điểm ngắm cảnh, xin chụp ảnh và kết thúc cuộc trò chuyện lịch sự.', 19),
(210, 2, 'Chọn quà lưu niệm cho gia đình', 'Hỏi ý nghĩa sản phẩm, xuất xứ và lựa chọn phù hợp.', 20),
(211, 2, 'Hỏi chất liệu và hàng thủ công', 'Phân biệt đồ thủ công, hỏi chất liệu và cách bảo quản.', 21),
(212, 2, 'Hỏi giá và thương lượng lịch sự ở chợ', 'Hỏi giá, đề nghị giảm khi mua nhiều và tôn trọng giá cố định.', 22),
(213, 2, 'Thanh toán và kiểm tra tiền thừa khi mua quà', 'Xác nhận tiền tệ, thanh toán thẻ và hỏi lại khi tiền thừa chưa đúng.', 23),
(214, 2, 'Gói quà và đóng gói đồ dễ vỡ', 'Yêu cầu gói quà, bọc bảo vệ và kiểm tra đồ trước khi mang về.', 24);
INSERT INTO phrases (phrase_id, lesson_id, english_text, vietnamese_meaning, ipa_phonetic, audio_sample_url, context_note) VALUES
(10501, 105, 'Welcome! What are you looking for today?', 'Xin chào! Hôm nay anh/chị đang tìm sản phẩm gì?', '/ˈwɛlkəm wʌt ɑr ju ˈlʊkɪŋ fɔr təˈdeɪ/', '', 'Nhân viên bán hàng đón khách, hỏi nhu cầu và ngân sách.'),
(10502, 105, 'Who is the gift for?', 'Món quà này dành cho ai?', '/hu ɪz ðə ɡɪft fɔr/', '', 'Nhân viên bán hàng đón khách, hỏi nhu cầu và ngân sách.'),
(10503, 105, 'What is your budget?', 'Ngân sách của anh/chị là bao nhiêu?', '/wʌt ɪz jʊr ˈbʌdʒɪt/', '', 'Nhân viên bán hàng đón khách, hỏi nhu cầu và ngân sách.'),
