(20602, 206, 'Where is the entrance for ticket holders?', 'Lối vào dành cho người đã có vé ở đâu?', '/wɛr ɪz ði ˈɛntrəns fɔr ˈtɪkɪt ˈhoʊldərz/', '', 'Hỏi vé, đặt trước và quy định chụp ảnh tại bảo tàng.'),
(20603, 206, 'Is photography allowed here?', 'Ở đây có được phép chụp ảnh không?', '/ɪz fəˈtɑɡrəfi əˈlaʊd hɪr/', '', 'Hỏi vé, đặt trước và quy định chụp ảnh tại bảo tàng.'),
(20604, 206, 'admission', 'quyền hoặc phí vào cửa', '/ədˈmɪʃən/', '', 'VOCABULARY'),
