(21306, 213, 'credit card', 'thẻ tín dụng', '/ˈkrɛdɪt kɑrd/', '', 'VOCABULARY'),
(21401, 214, 'Could you gift-wrap this, please?', 'Bạn có thể gói món này thành quà giúp tôi không?', '/kʊd ju ˈɡɪftˌræp ðɪs pliz/', '', 'Yêu cầu gói quà, bọc bảo vệ và kiểm tra đồ trước khi mang về.'),
(21402, 214, 'Please pack it carefully. It is fragile.', 'Vui lòng đóng gói cẩn thận. Món này dễ vỡ.', '/pliz pæk ɪt ˈkɛrfəli ɪt ɪz ˈfrædʒəl/', '', 'Yêu cầu gói quà, bọc bảo vệ và kiểm tra đồ trước khi mang về.'),
(21403, 214, 'Can I check the item before you wrap it?', 'Tôi có thể kiểm tra món đồ trước khi bạn gói không?', '/kæn aɪ tʃɛk ði ˈaɪtəm bɪˈfɔr ju ræp ɪt/', '', 'Yêu cầu gói quà, bọc bảo vệ và kiểm tra đồ trước khi mang về.'),
(21404, 214, 'gift wrapping', 'việc gói quà', '/ɡɪft ˈræpɪŋ/', '', 'VOCABULARY'),
(21405, 214, 'fragile', 'dễ vỡ', '/ˈfrædʒəl/', '', 'VOCABULARY'),
(21406, 214, 'bubble wrap', 'màng bọc chống sốc', '/ˈbʌbəl ræp/', '', 'VOCABULARY');
INSERT INTO scenarios (scenario_id, lesson_id, title, ai_role_name, user_role_name, context_briefing, initial_ai_greeting) VALUES
(504, 105, 'Chào khách và tìm hiểu nhu cầu mua hàng', 'Customer', 'Nhân viên bán hàng', 'Nhân viên bán hàng đón khách, hỏi nhu cầu và ngân sách.', 'Hello. I would like to buy a gift.'),
(505, 106, 'Giới thiệu sản phẩm và hướng dẫn dùng thử', 'Customer', 'Nhân viên bán hàng', 'Giải thích chất liệu, tính năng và mời khách dùng thử.', 'What is this bag made of?'),
(506, 107, 'Báo giá, giảm giá và xử lý so sánh giá', 'Customer', 'Nhân viên bán hàng', 'Giải thích giá niêm yết và ưu đãi cho khách.', 'How much is this item?'),
(507, 108, 'Chốt đơn và xác nhận thanh toán', 'Customer', 'Nhân viên bán hàng', 'Xác nhận lựa chọn, số lượng, phương thức thanh toán.', 'I would like to buy this one.'),
(508, 109, 'Đổi trả và chăm sóc khách sau mua', 'Customer', 'Nhân viên bán hàng', 'Tiếp nhận yêu cầu đổi sản phẩm, kiểm tra biên lai và chính sách.', 'I would like to return this bag.'),
(509, 205, 'Hỏi người bản địa đường đến tháp Eiffel', 'Local resident', 'Du khách', 'Hỏi đường, trạm tàu và lối đi bộ khi tham quan Paris.', 'Hello. Do you need directions?'),
(510, 206, 'Mua vé và hỏi quy định tại bảo tàng Louvre', 'Museum staff', 'Du khách', 'Hỏi vé, đặt trước và quy định chụp ảnh tại bảo tàng.', 'Welcome to the Louvre. How can I help?'),
(511, 207, 'Hỏi hướng dẫn viên tại đấu trường Colosseum', 'Tour guide', 'Du khách', 'Tìm tour tiếng Anh và hỏi về lịch sử công trình ở Rome.', 'Welcome. Would you like information about our tours?'),
(512, 208, 'Ứng xử lịch sự khi tham quan đền ở Kyoto', 'Local attendant', 'Du khách', 'Hỏi quy tắc, xin phép chụp ảnh và tôn trọng không gian tín ngưỡng.', 'Welcome. Is this your first visit?'),
(513, 209, 'Nhờ người bản địa gợi ý và chụp ảnh', 'Local resident', 'Du khách', 'Hỏi điểm ngắm cảnh, xin chụp ảnh và kết thúc cuộc trò chuyện lịch sự.', 'Hello. Are you looking for a place to take photos?'),
(514, 210, 'Chọn quà lưu niệm cho gia đình', 'Souvenir shopkeeper', 'Du khách', 'Hỏi ý nghĩa sản phẩm, xuất xứ và lựa chọn phù hợp.', 'Welcome. What kind of gift would you like?'),
(515, 211, 'Hỏi chất liệu và hàng thủ công', 'Artisan', 'Du khách', 'Phân biệt đồ thủ công, hỏi chất liệu và cách bảo quản.', 'Hello. Are you interested in this cup?'),
(516, 212, 'Hỏi giá và thương lượng lịch sự ở chợ', 'Market vendor', 'Du khách', 'Hỏi giá, đề nghị giảm khi mua nhiều và tôn trọng giá cố định.', 'Hello. Do you like this magnet?'),
(517, 213, 'Thanh toán và kiểm tra tiền thừa khi mua quà', 'Shopkeeper', 'Du khách', 'Xác nhận tiền tệ, thanh toán thẻ và hỏi lại khi tiền thừa chưa đúng.', 'How would you like to pay?'),
(518, 214, 'Gói quà và đóng gói đồ dễ vỡ', 'Souvenir shopkeeper', 'Du khách', 'Yêu cầu gói quà, bọc bảo vệ và kiểm tra đồ trước khi mang về.', 'Would you like this wrapped?');
INSERT INTO scenario_turns (scenario_id, step_order, expected_user_intent, bot_reaction_rules) VALUES
(504, 1, 'Welcome! What are you looking for today?', 'Hello. I would like to buy a gift.'),
(504, 2, 'Who is the gift for?', 'I am looking for something special.'),
(504, 3, 'What is your budget?', 'It is for my sister.'),
(504, 4, 'Thank you. Let me show you some options.', 'My budget is fifty dollars.'),
(505, 1, 'This bag is made of recycled materials.', 'What is this bag made of?'),
(505, 2, 'It is lightweight and easy to carry.', 'Is it comfortable to carry?'),
(505, 3, 'Would you like to try it?', 'Can I try it?'),
(505, 4, 'You are welcome. Take your time.', 'Thank you. It feels comfortable.'),
(506, 1, 'The price is thirty dollars.', 'How much is this item?'),
(506, 2, 'This price includes tax.', 'Does that include tax?'),
(506, 3, 'We can offer a ten percent discount.', 'Can you offer a discount?'),
(506, 4, 'Would you like to purchase it?', 'That sounds good.'),
(507, 1, 'Would you like one or two?', 'I would like to buy this one.'),
(507, 2, 'How would you like to pay?', 'Just one, please.'),
(507, 3, 'Here is your receipt.', 'I will pay by card.'),
(507, 4, 'You are welcome. Have a nice day!', 'Thank you for your help.'),
(508, 1, 'May I see your receipt?', 'I would like to return this bag.'),
(508, 2, 'Would you prefer an exchange or a refund?', 'Yes, here is my receipt.'),
(508, 3, 'Let me check our return policy.', 'I would prefer a refund.'),
(508, 4, 'I will check the policy and explain your options.', 'Can you tell me if that is possible?'),
(509, 1, 'Excuse me, how do I get to the Eiffel Tower?', 'Hello. Do you need directions?'),
(509, 2, 'Which metro station should I use?', 'Are you travelling by metro?'),
(509, 3, 'Is it within walking distance?', 'Would you like to walk from the station?'),
(509, 4, 'Thank you for your help.', 'You can check the route on your map.'),
(510, 1, 'Do I need to book a ticket in advance?', 'Welcome to the Louvre. How can I help?'),
(510, 2, 'Where is the entrance for ticket holders?', 'Have you already purchased a ticket?'),
(510, 3, 'Is photography allowed here?', 'Do you have any questions about the museum rules?'),
(510, 4, 'Thank you. I will follow the rules.', 'Please check the signs in each gallery.'),
(511, 1, 'Is there a guided tour in English?', 'Welcome. Would you like information about our tours?'),
(511, 2, 'How long does the tour take?', 'Do you have any questions before booking?'),
(511, 3, 'Could you tell me about the history of this place?', 'What would you like to learn about the Colosseum?'),
(511, 4, 'Thank you. That sounds interesting.', 'Our guide will explain the history during the tour.'),
(512, 1, 'Are there any rules I should follow?', 'Welcome. Is this your first visit?'),
(512, 2, 'Should I take off my shoes here?', 'Are you entering this building?'),
(512, 3, 'May I take a photo of this area?', 'Do you have a question about photography?'),
(512, 4, 'Thank you. I will be respectful.', 'Please look for signs before taking photos.'),
(513, 1, 'Could you recommend a good viewpoint?', 'Hello. Are you looking for a place to take photos?'),
(513, 2, 'Would you mind taking a photo of us?', 'This spot has a nice view.'),
(513, 3, 'Could you include the landmark in the background?', 'How would you like me to frame the photo?'),
(513, 4, 'Thank you so much for your help.', 'Here is your phone. I hope you like the photo.'),
(514, 1, 'I am looking for a small gift for my family.', 'Welcome. What kind of gift would you like?'),
(514, 2, 'Is this made locally?', 'Would you like to know where this item was made?'),
(514, 3, 'What does this design mean?', 'Do you have a question about the pattern?'),
(514, 4, 'Thank you. I would like to see the other designs.', 'I can explain its meaning and show you other designs.'),
(515, 1, 'Is this handmade?', 'Hello. Are you interested in this cup?'),
(515, 2, 'What is it made of?', 'Would you like to know about the material?'),
(515, 3, 'How should I take care of it?', 'Do you need advice on caring for it?'),
(515, 4, 'Yes, please. Thank you.', 'I can give you the care instructions.'),
(516, 1, 'How much is this magnet?', 'Hello. Do you like this magnet?'),
(516, 2, 'Is the price fixed?', 'It costs five dollars.'),
(516, 3, 'Could you offer a discount if I buy two?', 'We may have a discount for multiple items.'),
(516, 4, 'Thank you. Please let me know the total.', 'Let me check the price for two.'),
(517, 1, 'Can I pay in the local currency?', 'How would you like to pay?'),
(517, 2, 'Do you accept credit cards?', 'Would you prefer to use a card?'),
(517, 3, 'Could you check my change, please?', 'Here is your change. Is everything correct?'),
(517, 4, 'Thank you for checking.', 'Of course. Let me count it again.'),
(518, 1, 'Could you gift-wrap this, please?', 'Would you like this wrapped?'),
(518, 2, 'Please pack it carefully. It is fragile.', 'Are you taking it on a long journey?'),
(518, 3, 'Can I check the item before you wrap it?', 'Would you like to inspect it first?'),
(518, 4, 'Thank you. That would be helpful.', 'Of course. I will wrap it after you check it.');
